Deno.serve(async () => {
  const supabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
  );
  let inserted = 0;
  for (let i = 0; i < ROWS.length; i += 500) {
    const chunk = ROWS.slice(i, i + 500);
    const { error } = await supabase.from("uk_schools").upsert(chunk, { onConflict: "urn" });
    if (error) {
      return new Response(JSON.stringify({ error: error.message, at: i }), { status: 500 });
    }
    inserted += chunk.length;
  }
  return new Response(JSON.stringify({ inserted }), { headers: { "Content-Type": "application/json" } });
});
